package com.mahweb.mahyarnfc.omnishare.ble;
import android.Manifest; import android.app.Activity; import android.content.pm.PackageManager; import android.os.Build; import java.util.*;
public final class BlePermissions { public static final int REQUEST_CODE=4102; private BlePermissions(){} public static String[] needed(Activity a){List<String>n=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){add(a,n,Manifest.permission.BLUETOOTH_SCAN);add(a,n,Manifest.permission.BLUETOOTH_ADVERTISE);add(a,n,Manifest.permission.BLUETOOTH_CONNECT);}else add(a,n,Manifest.permission.ACCESS_FINE_LOCATION);return n.toArray(new String[0]);} private static void add(Activity a,List<String>n,String p){if(a.checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)n.add(p);} public static boolean has(Activity a){return needed(a).length==0;} }
